/* From Uiverse.io by Yaya12085 - Tags: card, paper, realistic */
.__UIV_SCOPE__ .papper {
  position: relative;
  box-sizing: border-box;
  width: 200px;
  height: 200px;
  background: #ffffff;
  background-image: linear-gradient(#ffffff 1.1rem, #ccc 1.2rem);
  background-size: 100% 1.2rem;
  border-radius: 10px;
  cursor: move;
}

.__UIV_SCOPE__ .papper::before,
.__UIV_SCOPE__ .papper::after {
  position: absolute;
  content: "";
  bottom: 10px;
  width: 40%;
  height: 10px;
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.7);
  z-index: -1;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .papper::before {
  left: 15px;
  transform: skew(-5deg) rotate(-5deg);
}

.__UIV_SCOPE__ .papper::after {
  right: 15px;
  transform: skew(5deg) rotate(5deg);
}

.__UIV_SCOPE__ .papper:hover::before,
.__UIV_SCOPE__ .papper:hover::after {
  box-shadow: 0 2px 14px rgba(0, 0, 0, 0.4);
}
